import React, { useState, useEffect, useRef } from 'react';
import { useStore } from '../../store/useStore';
import { apiGet, apiPost } from '../../utils/api';

var AWAY_LIMIT_SEC = 600; // 10 minutes

export default function VivaJoin() {
  var store = useStore();

  // Single phase variable drives everything
  // Values: 'join' | 'permission' | 'room' | 'away' | 'timeout' | 'ended'
  var [phase,         setPhase]         = useState('join');
  var [roomId,        setRoomId]        = useState('');
  var [invites,       setInvites]       = useState([]);
  var [session,       setSession]       = useState(null);
  var [camOk,         setCamOk]         = useState(false);
  var [micOk,         setMicOk]         = useState(false);
  var [permErr,       setPermErr]       = useState('');
  var [camOn,           setCamOn]           = useState(true);
  var [micOn,           setMicOn]           = useState(true);
  var [awayCountdown,   setAwayCountdown]   = useState(AWAY_LIMIT_SEC);
  var [adminConnected,  setAdminConnected]  = useState(false);

  var previewRef     = useRef(null);
  var selfVidRef     = useRef(null);   // student's own camera
  var adminVidRef    = useRef(null);   // admin's remote video
  var streamRef      = useRef(null);
  var peerRef        = useRef(null);   // RTCPeerConnection

  // Use refs for timers — never stale inside intervals
  var masterIntervalRef = useRef(null);  // single master tick every second
  var awayStartRef      = useRef(null);  // Date.now() when student left
  var inRoomRef         = useRef(false); // true when student is in the room
  var roomIdRef         = useRef('');    // always up-to-date roomId for intervals
  var sessionRef        = useRef(null);  // always up-to-date session
  var notifiedRef       = useRef(false); // sent away notification?
  var phaseRef          = useRef('join');// mirror of phase for use inside intervals

  // Keep refs in sync with state
  useEffect(function() { roomIdRef.current = roomId; }, [roomId]);
  useEffect(function() { sessionRef.current = session; }, [session]);
  useEffect(function() { phaseRef.current = phase; }, [phase]);

  // ── Load invitations ───────────────────────────────────────
  useEffect(function() { loadInvites(); }, []); // eslint-disable-line

  function loadInvites() {
    store.loadNotifications().then(function(notifs) {
      setInvites((notifs || []).filter(function(n) { return n.viva_room_id; }));
    });
  }

  // ── MASTER INTERVAL: runs every second once in room ───────
  // Handles both away countdown AND session-end polling
  // Never stopped/restarted on re-render — single stable interval
  function startMasterInterval() {
    clearInterval(masterIntervalRef.current);
    var pollTick = 0;  // poll every 5 seconds
    masterIntervalRef.current = setInterval(function() {
      var currentPhase = phaseRef.current;

      // ── Away countdown ──
      if (currentPhase === 'away' && awayStartRef.current) {
        var elapsed   = Math.floor((Date.now() - awayStartRef.current) / 1000);
        var remaining = AWAY_LIMIT_SEC - elapsed;
        setAwayCountdown(remaining > 0 ? remaining : 0);
        if (remaining <= 0) {
          awayStartRef.current = null;
          inRoomRef.current = false;
          phaseRef.current = 'timeout';
          setPhase('timeout');
          stopMedia();
          // Notify examiner
          apiPost('/notifications', {
            title:   'Student Removed — Viva Timeout',
            message: (store.currentUser.name || 'Student') +
              ' did not return within 10 minutes and was removed from "' +
              (sessionRef.current ? sessionRef.current.title : roomIdRef.current) + '".',
            type: 'urgent',
          }).catch(function(){});
        }
      }

      // ── Poll for session ended by examiner (every 5 ticks = 5s) ──
      pollTick++;
      if (pollTick >= 5) {
        pollTick = 0;
        var vid = roomIdRef.current;
        if (vid && (currentPhase === 'room' || currentPhase === 'away')) {
          apiGet('/viva/' + vid).then(function(s) {
            if (s && (s.status === 'ended' || s.status === 'locked')) {
              // Session ended by examiner — kick student
              clearInterval(masterIntervalRef.current);
              stopMedia();
              phaseRef.current = 'ended';
              setPhase('ended');
            }
          }).catch(function(){});
        }
      }
    }, 1000);
  }

  // ── Visibility change: ONLY this, NOT window.blur ─────────
  // Attached once on mount — reads phaseRef (always fresh) instead of phase
  useEffect(function() {
    var graceTimer = null;
    function onVisChange() {
      if (document.hidden) {
        // 2 second grace — ignore very fast tab switches
        graceTimer = setTimeout(function() {
          if (document.hidden && phaseRef.current === 'room') {
            goAway();
          }
        }, 2000);
      } else {
        // Tab is visible again
        clearTimeout(graceTimer);
        if (phaseRef.current === 'away') {
          // Student came back during countdown — return to room
          returnToRoom();
        }
      }
    }
    document.addEventListener('visibilitychange', onVisChange);
    return function() {
      document.removeEventListener('visibilitychange', onVisChange);
      clearTimeout(graceTimer);
    };
  }, []); // EMPTY deps — runs once, uses refs internally

  // ── Cleanup on unmount ────────────────────────────────────
  useEffect(function() {
    return function() {
      clearInterval(masterIntervalRef.current);
      stopMedia();
    };
  }, []); // eslint-disable-line

  function goAway() {
    if (awayStartRef.current) return; // already counting
    awayStartRef.current = Date.now();
    setAwayCountdown(AWAY_LIMIT_SEC);
    phaseRef.current = 'away';
    setPhase('away');
    // Notify examiner once
    if (!notifiedRef.current) {
      notifiedRef.current = true;
      apiPost('/notifications', {
        title:   'Student Left Viva Room',
        message: (store.currentUser.name || 'Student') +
          ' left "' + (sessionRef.current ? sessionRef.current.title : roomIdRef.current) +
          '". They have 10 min to return. Room: ' + roomIdRef.current,
        type: 'urgent',
      }).catch(function(){});
    }
  }

  function returnToRoom() {
    awayStartRef.current = null;
    notifiedRef.current  = false;
    setAwayCountdown(AWAY_LIMIT_SEC);
    phaseRef.current = 'room';
    setPhase('room');
    // Notify examiner
    apiPost('/notifications', {
      title:   'Student Returned to Viva Room',
      message: (store.currentUser.name || 'Student') +
        ' returned to "' + (sessionRef.current ? sessionRef.current.title : roomIdRef.current) + '".',
      type: 'success',
    }).catch(function(){});
    // Re-attach video
    setTimeout(function() {
      if (selfVidRef.current && streamRef.current) {
        selfVidRef.current.srcObject = streamRef.current;
      }
    }, 150);
  }

  function stopMedia() {
    if (peerRef.current) { try { peerRef.current.close(); } catch(e){} peerRef.current = null; }
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(function(t) { t.stop(); });
      streamRef.current = null;
    }
  }

  // ── Join room ──────────────────────────────────────────────
  async function handleJoin(id) {
    var vid = (id || roomId || '').trim();
    if (!vid) return;
    try {
      var s = await apiGet('/viva/' + vid);
      if (!s) { alert('Room not found'); return; }
      if (s.status === 'ended' || s.status === 'locked') {
        alert('This viva session has already ended.'); return;
      }
      setSession(s);
      sessionRef.current = s;
      setRoomId(vid);
      roomIdRef.current = vid;
      setPhase('permission');
      phaseRef.current = 'permission';
    } catch(e) { alert('Room not found: ' + e.message); }
  }

  // ── Permissions ────────────────────────────────────────────
  async function requestPermissions() {
    setPermErr('');
    try {
      var stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: true });
      streamRef.current = stream;
      setCamOk(true); setMicOk(true);
      var iv = setInterval(function() {
        if (previewRef.current) { previewRef.current.srcObject = stream; clearInterval(iv); }
      }, 200);
    } catch(e) {
      setPermErr(e.name === 'NotAllowedError'
        ? 'Permission denied. Click the camera icon in your browser bar, then try again.'
        : 'Camera/Mic access denied. Please allow in browser settings.');
    }
  }

  function enterRoom() {
    inRoomRef.current = true;
    phaseRef.current  = 'room';
    setPhase('room');
    // Attach own video
    setTimeout(function() {
      if (selfVidRef.current && streamRef.current) {
        selfVidRef.current.srcObject = streamRef.current;
      }
      // Start WebRTC after video attaches
      setupStudentWebRTC();
    }, 400);
    startMasterInterval();
  }

  async function setupStudentWebRTC() {
    var vid = roomIdRef.current || (sessionRef.current && sessionRef.current.viva_id);
    if (!vid || !streamRef.current) return;
    var token = localStorage.getItem('examai_token');
    var headers = { 'Content-Type':'application/json', Authorization:'Bearer '+token };
    try {
      var pc = new RTCPeerConnection({
        iceServers: [{ urls:'stun:stun.l.google.com:19302' }, { urls:'stun:stun1.l.google.com:19302' }]
      });
      peerRef.current = pc;
      // Add student tracks so admin can see/hear student
      streamRef.current.getTracks().forEach(function(t){ pc.addTrack(t, streamRef.current); });
      // When admin's video arrives
      pc.ontrack = function(e) {
        if (adminVidRef.current && e.streams && e.streams[0]) {
          adminVidRef.current.srcObject = e.streams[0];
          setAdminConnected(true);
        }
      };
      // Send ICE candidates
      pc.onicecandidate = function(e) {
        if (e.candidate) {
          fetch('http://localhost:5000/api/viva/' + vid + '/signal/candidate', {
            method:'POST', headers,
            body: JSON.stringify({ role:'student', candidate: e.candidate })
          }).catch(function(){});
        }
      };
      // Poll for admin's offer
      var offerPollCount = 0;
      var offerPoll = setInterval(async function() {
        offerPollCount++;
        if (offerPollCount > 30) { clearInterval(offerPoll); return; } // stop after 60s
        try {
          var r = await fetch('http://localhost:5000/api/viva/'+vid+'/signal/offer', { headers:{Authorization:'Bearer '+token} });
          var data = await r.json();
          if (data.offer && pc.remoteDescription === null) {
            clearInterval(offerPoll);
            await pc.setRemoteDescription(new RTCSessionDescription(data.offer));
            var answer = await pc.createAnswer();
            await pc.setLocalDescription(answer);
            await fetch('http://localhost:5000/api/viva/'+vid+'/signal/answer', {
              method:'POST', headers, body: JSON.stringify({ answer: pc.localDescription })
            });
            // Add admin ICE candidates
            var cr = await fetch('http://localhost:5000/api/viva/'+vid+'/signal/candidates/admin', { headers:{Authorization:'Bearer '+token} });
            var cd = await cr.json();
            (cd.candidates||[]).forEach(function(c){ pc.addIceCandidate(new RTCIceCandidate(c)).catch(function(){}); });
          }
        } catch(e2) {}
      }, 2000);
    } catch(e) { console.warn('Student WebRTC failed:', e); }
  }

  function toggleCam() {
    if (streamRef.current) {
      streamRef.current.getVideoTracks().forEach(function(t) { t.enabled = !camOn; });
      setCamOn(function(v) { return !v; });
    }
  }
  function toggleMic() {
    if (streamRef.current) {
      streamRef.current.getAudioTracks().forEach(function(t) { t.enabled = !micOn; });
      setMicOn(function(v) { return !v; });
    }
  }

  function leaveRoom() {
    clearInterval(masterIntervalRef.current);
    stopMedia();
    phaseRef.current = 'join';
    setPhase('join');
    setSession(null); sessionRef.current = null;
    setRoomId('');    roomIdRef.current  = '';
    setCamOk(false); setMicOk(false);
    awayStartRef.current = null;
    notifiedRef.current  = false;
  }

  // ══════════════════════════════════════════════════════════
  // ENDED BY EXAMINER
  // ══════════════════════════════════════════════════════════
  if (phase === 'ended') return (
    <div style={{ minHeight:'calc(100vh - 60px)', display:'flex', alignItems:'center', justifyContent:'center', background:'#0d0d14', padding:24 }}>
      <div style={{ textAlign:'center', background:'rgba(255,255,255,.05)', border:'1px solid rgba(255,255,255,.12)', borderRadius:20, padding:'44px 52px', maxWidth:460 }}>
        <div style={{ fontSize:'4rem', marginBottom:18 }}>🏁</div>
        <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:800, fontSize:'1.7rem', color:'#fff', marginBottom:12 }}>Viva Session Ended</div>
        <div style={{ fontSize:'0.9rem', color:'#9ca3af', lineHeight:1.75, marginBottom:28 }}>
          The examiner has ended this viva session.<br/>
          Your results will appear in <strong style={{color:'#a78bfa'}}>My Results</strong> after grading is complete.
        </div>
        <div style={{ padding:'10px 14px', background:'rgba(124,58,237,.12)', border:'1px solid rgba(124,58,237,.25)', borderRadius:10, marginBottom:24, fontSize:'0.82rem', color:'#a78bfa' }}>
          💡 Results are being finalized by your examiner. Check My Results in a few minutes.
        </div>
        <button className="btn btn-primary" onClick={function(){ leaveRoom(); }}>← Back to Viva Page</button>
      </div>
    </div>
  );

  // ══════════════════════════════════════════════════════════
  // TIMED OUT
  // ══════════════════════════════════════════════════════════
  if (phase === 'timeout') return (
    <div style={{ minHeight:'calc(100vh - 60px)', display:'flex', alignItems:'center', justifyContent:'center', background:'#0d0d14', padding:24 }}>
      <div style={{ textAlign:'center', background:'rgba(220,38,38,.06)', border:'1px solid rgba(220,38,38,.2)', borderRadius:20, padding:'44px 52px', maxWidth:460 }}>
        <div style={{ fontSize:'4rem', marginBottom:18 }}>⏰</div>
        <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:800, fontSize:'1.7rem', color:'#fff', marginBottom:12 }}>Session Expired</div>
        <div style={{ fontSize:'0.9rem', color:'#9ca3af', lineHeight:1.75, marginBottom:28 }}>
          You did not return within 10 minutes and were automatically removed from the viva room.<br/>Please contact your examiner.
        </div>
        <button className="btn btn-outline" onClick={function(){ leaveRoom(); }}>← Back to Viva Page</button>
      </div>
    </div>
  );

  // ══════════════════════════════════════════════════════════
  // AWAY — 10-MINUTE COUNTDOWN
  // ══════════════════════════════════════════════════════════
  if (phase === 'away') {
    var m = Math.floor(awayCountdown / 60);
    var s = awayCountdown % 60;
    var isUrgent = awayCountdown < 120;
    return (
      <div style={{ minHeight:'calc(100vh - 60px)', display:'flex', alignItems:'center', justifyContent:'center', flexDirection:'column', background:'#0d0d14', padding:24 }}>
        <div style={{ textAlign:'center' }}>
          <div style={{ fontSize:'4rem', marginBottom:16 }}>⏸</div>
          <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:800, fontSize:'1.9rem', color:'#fff', marginBottom:8 }}>You Left the Viva Room</div>
          <div style={{ fontSize:'0.9rem', color:'#9ca3af', marginBottom:32 }}>Your examiner has been notified. Return before the timer expires.</div>

          {/* Big countdown */}
          <div style={{
            fontFamily: 'JetBrains Mono,monospace',
            fontSize:   '5rem',
            fontWeight: 900,
            letterSpacing: 6,
            color:      isUrgent ? '#dc2626' : '#f59e0b',
            marginBottom: 12,
            textShadow: isUrgent ? '0 0 30px rgba(220,38,38,.5)' : '0 0 30px rgba(245,158,11,.3)',
          }}>
            {String(m).padStart(2,'0')}:{String(s).padStart(2,'0')}
          </div>

          <div style={{ fontSize:'0.9rem', color: isUrgent ? '#f87171' : '#6b7280', marginBottom:36, fontWeight: isUrgent ? 700 : 400 }}>
            {awayCountdown <= 0 ? 'Removing you…' : awayCountdown < 60 ? '⚠️ Less than a minute left!' : 'Return within ' + m + ' min ' + s + 's'}
          </div>

          <button className="btn btn-primary btn-lg" onClick={returnToRoom}
            style={{ padding:'14px 40px', fontSize:'1rem', boxShadow:'0 4px 20px rgba(124,58,237,.4)' }}>
            ▶ Return to Viva Room
          </button>

          <div style={{ marginTop:20, padding:'12px 20px', background:'rgba(220,38,38,.1)', border:'1px solid rgba(220,38,38,.25)', borderRadius:10, color:'#f87171', fontSize:'0.8rem', maxWidth:380 }}>
            ⚠️ Failing to return will remove you from the session automatically and notify your examiner.
          </div>
        </div>
      </div>
    );
  }

  // ══════════════════════════════════════════════════════════
  // JOIN
  // ══════════════════════════════════════════════════════════
  if (phase === 'join') return (
    <div className="fade-up">
      <div className="page-header">
        <div>
          <div className="page-title">🎙 Viva Voce</div>
          <div className="page-subtitle">Join your oral examination session</div>
        </div>
      </div>

      {invites.length > 0 && (
        <div style={{ marginBottom:28 }}>
          <div style={{ display:'flex', alignItems:'center', gap:10, marginBottom:14 }}>
            <div style={{ fontWeight:700, fontSize:'1rem' }}>📬 Your Viva Invitations</div>
            <button className="btn btn-ghost btn-sm" onClick={loadInvites}>↻ Refresh</button>
          </div>
          <div className="grid-2">
            {invites.map(function(inv) {
              return (
                <div key={inv.notification_id} className="card" style={{ borderLeft:'4px solid var(--accent)' }}>
                  <div style={{ fontWeight:700, marginBottom:6 }}>{inv.title}</div>
                  <div style={{ fontSize:'0.85rem', color:'var(--text3)', marginBottom:14 }}>{inv.message}</div>
                  <button className="btn btn-primary btn-sm" onClick={function(){ handleJoin(inv.viva_room_id); }}>🚀 Join Now</button>
                </div>
              );
            })}
          </div>
        </div>
      )}

      <div className="card" style={{ maxWidth:480 }}>
        <div className="card-title">Join by Room ID</div>
        <div style={{ display:'flex', gap:8, marginTop:12 }}>
          <input className="form-input" value={roomId} onChange={function(e){setRoomId(e.target.value); roomIdRef.current=e.target.value;}} placeholder="Paste Room ID here…" style={{ flex:1 }}/>
          <button className="btn btn-primary" onClick={function(){handleJoin();}} disabled={!roomId.trim()}>Join</button>
        </div>
        <div style={{ marginTop:12, fontSize:'0.8rem', color:'var(--text3)' }}>Ask your examiner for the Room ID if you don't have an invitation.</div>
      </div>
    </div>
  );

  // ══════════════════════════════════════════════════════════
  // PERMISSION
  // ══════════════════════════════════════════════════════════
  if (phase === 'permission') return (
    <div className="fade-up" style={{ maxWidth:520, margin:'40px auto', textAlign:'center' }}>
      <div style={{ fontSize:'3rem', marginBottom:12 }}>🎥</div>
      <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:800, fontSize:'1.4rem', marginBottom:6 }}>Camera &amp; Microphone</div>
      <div style={{ color:'var(--text3)', marginBottom:24 }}>Both are required for your viva session</div>

      <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:14, marginBottom:20 }}>
        {[{icon:camOk?'✅':'📷',label:'Camera',ok:camOk},{icon:micOk?'✅':'🎤',label:'Microphone',ok:micOk}].map(function(item,i){
          return (
            <div key={i} className="card" style={{ textAlign:'center', padding:20 }}>
              <div style={{ fontSize:'1.6rem', marginBottom:8 }}>{item.icon}</div>
              <div style={{ fontWeight:700 }}>{item.label}</div>
              <div style={{ fontSize:'0.8rem', color:item.ok?'var(--success)':'var(--text3)', marginTop:3 }}>{item.ok?'Ready ✓':'Pending'}</div>
            </div>
          );
        })}
      </div>

      {camOk && <div style={{ marginBottom:18 }}><video ref={previewRef} autoPlay muted playsInline style={{ width:'100%', maxWidth:320, borderRadius:12, background:'#000' }}/></div>}
      {permErr && <div style={{ padding:12, background:'rgba(220,38,38,.08)', border:'1px solid rgba(220,38,38,.2)', borderRadius:8, color:'var(--danger)', fontSize:'0.85rem', marginBottom:16 }}>{permErr}</div>}

      {!camOk
        ? <button className="btn btn-primary btn-lg" onClick={requestPermissions}>🔓 Grant Camera &amp; Mic Access</button>
        : <button className="btn btn-success btn-lg" onClick={enterRoom}>🚀 Enter Viva Room</button>
      }
    </div>
  );

  // ══════════════════════════════════════════════════════════
  // ROOM
  // ══════════════════════════════════════════════════════════
  return (
    <div className="viva-dark fade-up">
      <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:18, flexWrap:'wrap', gap:10 }}>
        <div style={{ display:'flex', alignItems:'center', gap:12 }}>
          <span className="badge badge-success">🟢 Connected</span>
          <span style={{ fontWeight:700, color:'#fff', fontSize:'1.05rem' }}>{session ? session.title : 'Viva Session'}</span>
          {session && session.topic && <span className="badge badge-primary" style={{fontSize:'0.68rem'}}>{session.topic}</span>}
        </div>
        <div style={{ display:'flex', gap:8 }}>
          <button className="btn btn-sm btn-outline" onClick={function(){if(window.confirm('Leave the viva room?'))leaveRoom();}}>Leave Room</button>
        </div>
      </div>

      <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:16, maxWidth:860, margin:'0 auto' }}>
        {/* Student's own camera */}
        <div className="card" style={{ padding:12 }}>
          <div style={{ position:'relative', borderRadius:8, overflow:'hidden', background:'#000', lineHeight:0 }}>
            <video ref={selfVidRef} autoPlay muted playsInline style={{ width:'100%', height:200, objectFit:'cover', display:'block' }}/>
            <div style={{ position:'absolute', bottom:6, left:'50%', transform:'translateX(-50%)', background:'rgba(0,0,0,.6)', color:'#fff', fontSize:'0.62rem', padding:'2px 10px', borderRadius:10, whiteSpace:'nowrap', fontWeight:600 }}>You ({store.currentUser.name})</div>
          </div>
          <div style={{ display:'flex', gap:8, marginTop:8, justifyContent:'center' }}>
            <button className={'btn btn-sm '+(camOn?'btn-success':'btn-outline')} onClick={toggleCam} style={{fontSize:'0.72rem',padding:'3px 10px'}}>{camOn?'📷 Cam On':'📷 Cam Off'}</button>
            <button className={'btn btn-sm '+(micOn?'btn-success':'btn-outline')} onClick={toggleMic} style={{fontSize:'0.72rem',padding:'3px 10px'}}>{micOn?'🎤 Mic On':'🎤 Mic Off'}</button>
          </div>
        </div>
        {/* Admin/Examiner live video via WebRTC */}
        <div className="card" style={{ padding:12 }}>
          <div style={{ position:'relative', borderRadius:8, overflow:'hidden', background:'#111', lineHeight:0 }}>
            <video ref={adminVidRef} autoPlay playsInline style={{ width:'100%', height:200, objectFit:'cover', display:'block' }}/>
            {!adminConnected && <div style={{ position:'absolute', inset:0, display:'flex', alignItems:'center', justifyContent:'center', flexDirection:'column', gap:6 }}>
              <div style={{ fontSize:'2.5rem', opacity:.3 }}>👨‍🏫</div>
              <div style={{ fontSize:'0.72rem', color:'#4b5563', fontWeight:600 }}>Waiting for examiner…</div>
              <div style={{ fontSize:'0.65rem', color:'#374151' }}>Audio & video will connect shortly</div>
            </div>}
            {adminConnected && <div style={{ position:'absolute', bottom:6, left:'50%', transform:'translateX(-50%)', background:'rgba(22,163,74,.85)', color:'#fff', fontSize:'0.62rem', padding:'2px 10px', borderRadius:10, whiteSpace:'nowrap', fontWeight:700 }}>🟢 Examiner Live</div>}
          </div>
          <div style={{ textAlign:'center', marginTop:8, fontSize:'0.78rem', color: adminConnected?'#4ade80':'#6b7280', fontWeight:600 }}>
            {adminConnected ? '🟢 Examiner connected — speak clearly' : '⏳ Connecting to examiner…'}
          </div>
        </div>
      </div>

      <div style={{ maxWidth:860, margin:'12px auto 0', padding:'10px 14px', background:'rgba(124,58,237,.1)', border:'1px solid rgba(124,58,237,.25)', borderRadius:10, fontSize:'0.8rem', color:'#a78bfa', textAlign:'center' }}>
        🎤 Speak clearly into your mic. Your examiner can see and hear you live. Switching browser tabs will notify your examiner and start a 10-minute countdown.
      </div>
    </div>
  );
}
